function applyImportedConfiguration(snapshot){
 const stored=snapshot?.localStorage;
 if(snapshot?.format!=='One Browser data'||snapshot?.version!==1||!stored||typeof stored!=='object'||Array.isArray(stored)||Object.values(stored).some(value=>typeof value!=='string'))throw new Error('配置文件格式无效，未修改当前设置');
 if(environments.some(entry=>entry.state==='running'||entry.starting||entry.restarting))throw new Error('请先关闭全部浏览器窗口再加载配置');
 const before=Object.fromEntries(Object.keys(localStorage).map(key=>[key,localStorage.getItem(key)])),next={...stored};delete next['one-browser-local-data'];
 for(const [key,expected] of [['one-browser-environments','array'],['one-browser-accounts','array'],['one-browser-proxy-nodes','array']]){if(next[key]!==undefined){let parsed;try{parsed=JSON.parse(next[key])}catch(_){throw new Error('配置数据无效，未修改当前设置')}if(!Array.isArray(parsed)||parsed.some(item=>!item||typeof item!=='object'||Array.isArray(item)))throw new Error('配置数据无效，未修改当前设置')}}
 for(const [key,field] of [['one-browser-environments','name'],['one-browser-accounts','service'],['one-browser-proxy-nodes','name']])for(const item of JSON.parse(next[key]||'[]'))if(typeof item[field]!=='string'||!item[field].trim())throw new Error('配置列表缺少有效名称，未修改当前设置');
 for(const key of ['one-browser-kernels','one-browser-kernel-versions','one-browser-window-profiles-v2'])if(next[key]!==undefined){let value;try{value=JSON.parse(next[key])}catch(_){throw new Error('配置数据无效，未修改当前设置')}if(!value||typeof value!=='object'||Array.isArray(value))throw new Error('配置数据无效，未修改当前设置')}
 // Machine-local profile bindings must never be imported from another computer.
 const bindings=JSON.parse(before['one-browser-window-profiles-v2']||'{}');const entries=JSON.parse(next['one-browser-environments']||'[]');
 for(const entry of entries){const local=environments.find(item=>item.windowId===entry.windowId);entry.profileId=bindings[entry.windowId]||local?.profileId||'';entry.state='stopped';delete entry.starting;delete entry.restarting}
 next['one-browser-environments']=JSON.stringify(entries);next['one-browser-window-profiles-v2']=JSON.stringify(Object.fromEntries(entries.filter(entry=>entry.profileId).map(entry=>[entry.windowId,entry.profileId])));
 for(const key of ['one-browser-kernels','one-browser-kernel-versions'])if(before[key]!==undefined)next[key]=before[key];
 try{localStorage.clear();Object.entries(next).forEach(([key,value])=>localStorage.setItem(key,value))}catch(error){localStorage.clear();Object.entries(before).forEach(([key,value])=>localStorage.setItem(key,value));throw new Error('配置保存失败，已恢复原有设置')}
}
