let toastHideTimer=0;function showToast(message,options={}){const text=String(message||''),failed=/失败|错误|无法|未就绪|Timeout/i.test(text),warning=!failed&&/请先|取消|未安装|未获取/.test(text),t=document.querySelector('#toast');t.classList.toggle('is-error',failed);t.classList.toggle('is-warning',warning);t.innerHTML=icon(failed?'circle-alert':warning?'circle-help':'check')+`<span>${safeInline(text)}</span>`;t.classList.add('show');window.clearTimeout(toastHideTimer);toastHideTimer=window.setTimeout(()=>t.classList.remove('show'),2600);if(options.log!==false)window.onlineDesktop?.logOperation?.(failed?'error':'info','OneBrowserUI',!failed,text)?.catch?.(()=>{})}
