function accountTransferFingerprint(a){return JSON.stringify([a.service,a.identity||'',a.owner||''])}
function mergeAccountImport(records){if(!Array.isArray(records)||records.length>5000)throw new Error('账号文件格式无效');const seen=new Set(managedAccounts.map(accountTransferFingerprint)),used=new Set(managedAccounts.map(a=>a.accountId)),newAccounts=[];let skipped=0;for(const item of records){if(!item||typeof item.service!=='string'||!item.service.trim()||typeof item.identity!=='string'||typeof item.owner!=='string')throw new Error('账号资料格式无效，未导入任何账号');const candidate={service:item.service,identity:item.identity,owner:item.owner},fingerprint=accountTransferFingerprint(candidate);if(seen.has(fingerprint)){skipped++;continue}let id=typeof item.accountId==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(item.accountId)?item.accountId:'';if(!id||used.has(id))id=windowIdentity.newID();used.add(id);seen.add(fingerprint);newAccounts.push({...candidate,accountId:id,window:''})}const next=[...managedAccounts,...newAccounts];if(next.length>5000)throw new Error('导入后账号总数不能超过 5000');window.OneBrowserAccountAppearance.normalize(next);localStorage.setItem('one-browser-accounts',JSON.stringify(next));managedAccounts.push(...newAccounts);renderAccounts();render(currentFilter,document.querySelector('#search').value);return {added:newAccounts.length,skipped}}
