function buildDataZip(){const encoder=new TextEncoder(),content=encoder.encode(JSON.stringify(collectBackupData(),null,2)),name=encoder.encode('data/one-browser-data.json'),crc=crc32(content),local=zipHeader(30+name.length),central=zipHeader(46+name.length);local.u32(0,0x04034b50);local.u16(4,20);local.u16(6,0x0800);local.u16(8,0);local.u32(14,crc);local.u32(18,content.length);local.u32(22,content.length);local.u16(26,name.length);local.bytes.set(name,30);central.u32(0,0x02014b50);central.u16(4,20);central.u16(6,20);central.u16(8,0x0800);central.u16(10,0);central.u32(16,crc);central.u32(20,content.length);central.u32(24,content.length);central.u16(28,name.length);central.u32(42,0);central.bytes.set(name,46);const end=zipHeader(22);end.u32(0,0x06054b50);end.u16(8,1);end.u16(10,1);end.u32(12,central.bytes.length);end.u32(16,local.bytes.length+content.length);return new Blob([joinBytes([local.bytes,content,central.bytes,end.bytes])],{type:'application/zip'})}
