 [...select.children].forEach(item=>{
  if(item.tagName==='OPTGROUP'){
   const label=document.createElement('div');label.className='rounded-select-group';label.textContent=item.label;roundedSelectPopover.appendChild(label);
   [...item.children].forEach(option=>appendRoundedOption(option,select));
  }else if(item.tagName==='OPTION')appendRoundedOption(item,select);
 });
 const rect=trigger.getBoundingClientRect(),spaceBelow=Math.max(0,window.innerHeight-rect.bottom-17),spaceAbove=Math.max(0,rect.top-17),openBelow=spaceBelow>=Math.min(180,roundedSelectPopover.childElementCount*38+12)||spaceBelow>=spaceAbove,maxHeight=Math.max(34,Math.min(280,openBelow?spaceBelow:spaceAbove)),estimated=Math.min(maxHeight,roundedSelectPopover.childElementCount*38+12);
