/* Every lightweight surface participates in one capture-phase exclusivity
   controller. Buttons may stop click bubbling, but pointer capture still closes
   the previously open surface before the next one is toggled. */
function closeTransientSurfaces(except=''){
 closeHeaderPopovers(['upgrade','cloud','kernel'].includes(except)?except:'');
 if(except!=='advanced')closeAdvancedFilter();
 if(except!=='table')closeTablePopovers();
 if(except!=='row')closeRowMenu();
 if(except!=='account')closeAccountMenu();
 if(except!=='rounded'&&!(except==='kernel'&&activeRoundedSelect?.closest('#kernelManagerModal')))closeRoundedSelect();
}
function transientGroupForTarget(target){
 if(target.closest('.rounded-select-popover')&&activeRoundedSelect?.closest('#kernelManagerModal'))return'kernel';
 if(target.closest('#coreUpdateBtn,#coreUpdatePopover'))return'upgrade';
 if(target.closest('#cloudBackupBtn,#cloudBackupPopover'))return'cloud';
 if(target.closest('.kernel-download,#kernelManagerModal'))return'kernel';
 if(target.closest('#advancedFilterBtn,#advancedFilterPopover'))return'advanced';
 if(target.closest('.config-tool,#tagMenu,#profileMenu,#windowColorPopover,[data-action="tag"],[data-action="profile"],[data-action="color"]'))return'table';
 if(target.closest('#rowMenu,[data-action="menu"]'))return'row';
 if(target.closest('#currentAccount,#accountMenu'))return'account';
 if(target.closest('.rounded-select-trigger,.rounded-select-popover'))return'rounded';
 return'';
}
document.addEventListener('pointerdown',event=>{const target=event.target instanceof Element?event.target:null;closeTransientSurfaces(target?transientGroupForTarget(target):'')},true);

/* Esc closes the topmost transient surface everywhere in the application. */
document.addEventListener('keydown',event=>{
 if(event.key!=='Escape')return;
 if(roundedSelectPopover.classList.contains('open')){event.preventDefault();closeRoundedSelect();return}
 const proxyImport=document.querySelector('#proxyImportModal.show');if(proxyImport){event.preventDefault();document.querySelector('#closeProxyImport')?.click();return}
 const openModals=[...document.querySelectorAll('.modal-backdrop.open')];if(openModals.length){event.preventDefault();const modal=openModals.at(-1),close=modal.querySelector('[id^="close"],[id^="cancel"],[id^="confirmConfigDetail"]');if(close)close.click();else modal.classList.remove('open');return}
 if(cloudBackupPopover.classList.contains('open')){event.preventDefault();closeCloudBackup();return}
 if(coreUpdatePopover.classList.contains('open')){event.preventDefault();coreUpdatePopover.classList.remove('open');return}
 if(advancedFilterPopover.classList.contains('open')){event.preventDefault();closeAdvancedFilter();return}
 const color=document.querySelector('#windowColorPopover.open');if(color){event.preventDefault();document.querySelector('#closeWindowColor')?.click();return}
 const transient=document.querySelector('.row-menu.open,.account-popover.open,.tag-menu.open,.profile-menu.open');if(transient){event.preventDefault();transient.classList.remove('open')}
});

