if(desktopBridge()?.syncWindowDirectories){window.oneBrowserDirectorySync=desktopBridge().syncWindowDirectories(environments).then(warnings=>{if(warnings?.length)showToast('部分窗口目录尚未同步：'+warnings.join('；'))}).catch(error=>showToast(error.message||'窗口目录同步失败'))}

const deleteWindowModal=document.querySelector('#deleteWindowModal');let pendingDeleteWindow=null,windowDeleteBusy=false;
function openDeleteWindow(entry){if(!entry)return;if(entry.state==='running'||entry.starting)return showToast('浏览器仍在运行或启动中，请先关闭或停止该窗口后再删除');pendingDeleteWindow=entry;document.querySelector('#deleteWindowText').textContent=`确定删除“${entry.name}”及其浏览器数据吗？Cookie、已保存密码、标签会话和插件数据将一并删除，无法恢复。`;deleteWindowModal.classList.add('open')}
function closeDeleteWindow(){if(windowDeleteBusy)return;deleteWindowModal.classList.remove('open');pendingDeleteWindow=null}
document.querySelector('#cancelDeleteWindow').onclick=closeDeleteWindow;deleteWindowModal.onclick=event=>{if(event.target===deleteWindowModal)closeDeleteWindow()};
async function deleteEnvironment(entry){await window.oneBrowserDirectorySync;if(entry.state==='running'||entry.starting)throw new Error('浏览器仍在运行或启动中，请先关闭或停止该窗口后再删除');const desktop=desktopBridge();if(!desktop?.deleteBrowserWindow)throw new Error('窗口删除服务未就绪');await desktop.deleteBrowserWindow({id:entry.windowId,profileId:entry.profileId||''});const index=environments.indexOf(entry);if(index>=0)environments.splice(index,1);selectedEnvironmentIndexes.clear();render(currentFilter,document.querySelector('#search').value)}
document.querySelector('#confirmDeleteWindow').onclick=async()=>{const entry=pendingDeleteWindow;if(!entry||windowDeleteBusy)return;windowDeleteBusy=true;const button=document.querySelector('#confirmDeleteWindow');button.disabled=true;button.textContent='正在删除';try{await deleteEnvironment(entry);windowDeleteBusy=false;closeDeleteWindow();showToast(`“${entry.name}”及对应数据已删除`)}catch(error){showToast(error.message||'删除失败，窗口记录已保留')}finally{windowDeleteBusy=false;button.disabled=false;button.textContent='删除窗口及数据'}};

const cleanupDetachedModal=document.querySelector('#cleanupDetachedModal');let detachedCandidates=[],detachedBusy=false;
function closeDetachedCleanup(){if(detachedBusy)return;cleanupDetachedModal.classList.remove('open');detachedCandidates=[]}
document.querySelector('#cancelCleanupDetached').onclick=closeDetachedCleanup;cleanupDetachedModal.onclick=e=>{if(e.target===cleanupDetachedModal)closeDetachedCleanup()};
document.querySelector('#cleanupDetachedWindows').onclick=async event=>{const button=event.currentTarget;button.disabled=true;try{await window.oneBrowserDirectorySync;const desktop=desktopBridge();if(!desktop?.listDetachedWindows)throw new Error('清理服务未就绪');const entries=await desktop.listDetachedWindows(environments.map(entry=>entry.windowId));detachedCandidates=entries.filter(entry=>!entry.running);const running=entries.length-detachedCandidates.length;if(!detachedCandidates.length)return showToast(running?'发现运行中的遗留浏览器，请先关闭后重试':'没有发现可清理的遗留窗口');document.querySelector('#cleanupDetachedText').textContent=`以下窗口已不在当前列表：${detachedCandidates.map(entry=>entry.name).join('、')}。确认后永久删除对应 Cookie、密码、会话及插件数据，无法恢复。`+(running?`另有 ${running} 个运行中的窗口不会清理。`:'');cleanupDetachedModal.classList.add('open')}catch(error){showToast(error.message||'检查失败')}finally{button.disabled=false}};
document.querySelector('#confirmCleanupDetached').onclick=async event=>{if(detachedBusy)return;detachedBusy=true;const button=event.currentTarget;button.disabled=true;let removed=0;try{const desktop=desktopBridge();for(const entry of [...detachedCandidates]){if(environments.some(item=>item.windowId===entry.windowId))throw new Error('窗口列表已变化，请重新检查');await desktop.deleteBrowserWindow({id:entry.windowId,profileId:entry.profileId});detachedCandidates=detachedCandidates.filter(item=>item.windowId!==entry.windowId);removed++}detachedBusy=false;closeDetachedCleanup();showToast(`已清理 ${removed} 个遗留窗口的数据`)}catch(error){detachedBusy=false;closeDetachedCleanup();showToast(`已清理 ${removed} 个；${error.message||'其余未完成，请重新检查'}`)}finally{detachedBusy=false;button.disabled=false}};

document.querySelector('#environments>.table-wrap').addEventListener('scroll',()=>{closeTablePopovers();closeRowMenu()},{passive:true});
